import{d as g,C as t,o as h,c as d,j as e,a as i,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"中庸·第9章","description":"《中庸》第 9 章——天下可均、爵禄可辞、白刃可蹈，唯独中庸不可能：三者难而易，中庸易而难。","frontmatter":{"title":"中庸·第9章","description":"《中庸》第 9 章——天下可均、爵禄可辞、白刃可蹈，唯独中庸不可能：三者难而易，中庸易而难。","category":"guide","aliases":["第9章","中庸第9章","中庸不可能"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-09.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-09.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-09.md"},f=g({...m,setup(p){const o=[{id:"sannan",label:"天下可均 · 爵禄可辞 · 白刃可蹈",showLabel:!0,sentences:[["子曰：“天下国家可",{text:"均",glossary:"jun"},"也，",{text:"爵禄",glossary:"juelu"},"可",{text:"辞",glossary:"ci"},"也，",{text:"白刃",glossary:"bairen"},"可",{text:"蹈",glossary:"dao"},"也，"]],note:"孔子先列三件极难之事：天下国家可以平均分配（均），爵禄可以辞让不受，白刃可以踩上去（蹈）——此三者皆常人所难能。"},{id:"bukeneng",label:"中庸不可能也",showLabel:!0,sentences:[["中庸",{text:"不可能",glossary:"bukeneng"},"也。”"]],note:"然而「中庸不可能也」——唯有中庸做不到。前三者只需一时之勇或一节之操，中庸却要「时中」而恒常，故独难。此章以三难反衬中庸之难。"}],s=[{id:"jun",term:"均",pinyin:"jūn",meaning:"平治、均平。"},{id:"juelu",term:"爵禄",pinyin:"jué lù",meaning:"爵位与俸禄。"},{id:"ci",term:"辞",pinyin:"cí",meaning:"辞让、推辞。"},{id:"bairen",term:"白刃",pinyin:"bái rèn",meaning:"锋利的刀刃。"},{id:"dao",term:"蹈",pinyin:"dǎo",meaning:"踩、踏。此处指赴刃而行。"},{id:"bukeneng",term:"不可能",pinyin:"bù kě néng",meaning:"做不到。非「绝无可能」之义，而是说极难做到——朱注：「非义精仁熟，而无一毫人欲之私者，不能及也。」"},{id:"yijingrenshu",term:"义精仁熟",pinyin:"yì jīng rén shú",meaning:"义理精纯、仁德成熟。朱注以此四字说中庸之所以难——不难在用力，难在无私。"}];return(c,n)=>{const l=t("DaoTextReading"),r=t("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=e("h1",{id:"中庸·第9章",tabindex:"-1"},[i("中庸·第9章 "),e("a",{class:"header-anchor",href:"#中庸·第9章","aria-label":'Permalink to "中庸·第9章"'},"​")],-1)),n[1]||(n[1]=e("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),e("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=e("p",null,[i("本章用三件「天下至难」之事作反衬：平治天下、辞让爵禄、赴白刃——这三样都有人做得到；"),e("strong",null,"唯独中庸，几乎无人能做到"),i("。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"天下可均 · 爵禄可辞 · 白刃可蹈 · 中庸不可能",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第9章 原文"}),n[3]||(n[3]=e("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),e("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(r,{items:[{term:"均",pinyin:["jūn"],meaning:"平治、均平。"},{term:"爵禄",pinyin:["jué","lù"],meaning:"爵位与俸禄。"},{term:"辞",pinyin:["cí"],meaning:"辞让、推辞。"},{term:"白刃",pinyin:["bái","rèn"],meaning:"锋利的刀刃。"},{term:"蹈",pinyin:["dǎo"],meaning:"踩、踏。此处指赴刃而行。"}]}),a(r,{items:[{term:"不可能",pinyin:["bù","kě","néng"],meaning:"做不到。非「绝无可能」之义，而是极难做到——朱注：「非义精仁熟，而无一毫人欲之私者，不能及也。」"},{term:"难而易",pinyin:["nán","ér","yì"],meaning:"朱注：「三者难而易」——均天下、辞爵禄、蹈白刃三件难事，凭资质勇力近似者也能做到。"},{term:"易而难",pinyin:["yì","ér","nán"],meaning:"朱注：「中庸易而难」——中庸看似寻常，却非无私不能及。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>天下可均 · 爵禄可辞 · 白刃可蹈</strong>：天下国家可以平治，爵位俸禄可以辞让，锋利的刀刃可以踩上去。</p><p><strong>中庸不可能也</strong>：唯有中庸，却做不到。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第九章先举三件「天下之至难」：平治天下、辞让爵禄、赴白刃——<strong>这三样都有人能做到</strong>；然后一转：「中庸不可能也。」</p><p>不是中庸比这三件事更费力，而是它的难处在别的地方。朱注一句点透：「<strong>三者难而易，中庸易而难。</strong>」</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「难」重新定义了</strong>：三件难事之所以「易」，是因为凭资质与勇力的近似者都能做到；中庸之所以「难」，是因为它的条件是——「<strong>义精仁熟，而无一毫人欲之私</strong>」。<strong>难不在用力，难在无私。</strong></li><li><strong>它与前几章构成一条递进线</strong>：第 3 章说「民鲜能久」（难在不能长），第 7 章说「不能期月守」（难在不能守），本章说「不可能」（难在不能无私）。三处递进，越来越指向内里。</li><li><strong>它防住了两种自负</strong>：既防「我把难事做成了，所以我行」，也防「中庸太容易，不必当真」。</li><li><strong>朱注还留了一句</strong>：「此民之所以鲜能也」——第 3 章的「鲜能」由此得到解释。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>区分两种难</strong>：靠冲劲能办成的，是「三难」；要日日无私才能办成的，是「中庸」。</li><li><strong>把判断落到「私」上</strong>：这件事我做到了，里面有没有一分是为人欲？这才是本章的切口。</li><li><strong>别用「难」开脱</strong>：三难都有人做到，说明「能不能」很少是问题；问题在愿不愿意去私。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：平治天下、辞让爵禄、踩着白刃走过去——这三件极难的事，都有人做得到；可是<strong>中庸，做不到</strong>。</p><p>朱熹的解释是：三件事难在用力，所以资质相近、肯下力的人就能做到；中庸不难在用力，它难在「<strong>义精仁熟，而无一毫人欲之私</strong>」。换句话说——<strong>难的不是做大事，是每一处都不掺私。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「三者难而易，中庸易而难」——我做成过哪些「难事」？它们里面有多少是靠冲劲，有多少是靠无私？</li><li>「义精仁熟，而无一毫人欲之私」——用「有没有掺私」检验我最近的一个决定，结果如何？</li><li>这一章为什么把「中庸」放在三件大事之后来说？若换成先说中庸，力量会不会不同？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-08">中庸·第8章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-10">中庸·第10章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',21))])}}});export{y as __pageData,f as default};
